function stable(node){return getData(node,'stable-id')}
function currentRevn(host){const value=Number(host&&host.penpot&&host.penpot.currentFile&&host.penpot.currentFile.revn);ok(Number.isInteger(value)&&value>=DATA.protected.minimum_revn,'CURRENT_REVN_UNAVAILABLE');return value}
