function assertActive(host){const auth=host&&host.authorization;ok(auth&&auth.schema===AUTH_SCHEMA,'AUTHORIZATION_SCHEMA');ok(auth.package_id===DATA.package_id,'AUTHORIZATION_PACKAGE');const provider=expectedProvider();for(const key of PROVIDER_FIELDS)ok(canonical(auth[key])===canonical(provider[key]),'AUTHORIZATION_PROVIDER_IDENTITY:'+key);ok(/^[0-9a-f]{40}$/.test(auth.package_head||''),'AUTHORIZATION_HEAD');ok(/^[0-9a-f]{40}$/.test(auth.package_tree||''),'AUTHORIZATION_TREE');ok(/^[0-9a-f]{64}$/.test(auth.bundle_sha256||''),'AUTHORIZATION_BUNDLE_SHA');ok(typeof auth.session_id==='string'&&auth.session_id,'AUTHORIZATION_SESSION');ok(typeof auth.task_id==='string'&&auth.task_id,'AUTHORIZATION_TASK');ok(auth.writer_id==='/root/publish_r2','AUTHORIZATION_WRITER');ok(typeof auth.triggered_by==='string'&&auth.triggered_by,'AUTHORIZATION_TRIGGER');ok(typeof auth.lease_token==='string'&&auth.lease_token,'AUTHORIZATION_LEASE');ok(typeof auth.cancel_token==='string'&&auth.cancel_token,'AUTHORIZATION_CANCEL');ok(Number.isFinite(Date.parse(auth.expires_at))&&Date.parse(auth.expires_at)>Date.now(),'AUTHORIZATION_EXPIRED');ok(auth.requirements_contract_sha256===DATA.requirements_contract.sha256,'AUTHORIZATION_REQUIREMENTS_CONTRACT');ok(auth.source_bundle_head===DATA.source_bundle.head&&auth.source_bundle_tree===DATA.source_bundle.tree&&auth.source_bundle_sha256===DATA.source_bundle.sha256,'AUTHORIZATION_SOURCE_BUNDLE');ok(auth.atlas_head===DATA.atlas.head&&auth.atlas_tree===DATA.atlas.tree,'AUTHORIZATION_ATLAS');ok(auth.atlas_page_id===DATA.atlas.atlas_page_id&&auth.atlas_page_order===DATA.atlas.page_order&&auth.atlas_template_id===DATA.atlas.template_id,'AUTHORIZATION_ATLAS_PAGE');ok(auth.native_revn===currentRevn(host)&&auth.protected_projection_revn===currentRevn(host),'AUTHORIZATION_REVN');ok(/^[0-9a-f]{64}$/.test(auth.protected_projection_sha256||''),'AUTHORIZATION_PROTECTED_SHA');ok(auth.header_component_id===DATA.atlas.header_component_id&&auth.header_main_id===DATA.atlas.header_main_id,'AUTHORIZATION_HEADER');ok(canonical(auth.source_component_ids)===canonical(DATA.families.map((item)=>item.component_id)),'AUTHORIZATION_SOURCE_COMPONENTS');ok(canonical(auth.source_main_ids)===canonical(DATA.families.map((item)=>item.main_id)),'AUTHORIZATION_SOURCE_MAINS');ok(auth.source_projection_sha256===DATA.source_projection_sha256,'AUTHORIZATION_SOURCE_PROJECTION');const active=readActive(host);ok(active.state==='ACTIVE'&&active.cancelled!==true,'PHYSICAL_ACTIVE_CANCELLED');for(const key of PARITY_FIELDS)ok(canonical(active[key])===canonical(auth[key]),'PHYSICAL_ACTIVE_TUPLE_MISMATCH:'+key);return active}
