async function resize(host,node,width,height){if(typeof node.resize==='function'){const pending=guarded(host,()=>node.resize(width,height));await pending;assertActive(host)}else{set(host,node,'width',width);set(host,node,'height',height)}ok(Number(node.width)===width&&Number(node.height)===height,'ASYNC_RESIZE_NOT_SETTLED')}
